import * as T from './vendor/three.module.js';import {compactSurface} from './map-batches.js';import {ClusterVisibility} from './map-cluster-visibility.js';import {optimizeMapMaterial} from './map-material-performance.js';

// Complete source solids remain independent of exact weapon/movement meshes.
// Every repeated prop references one immutable vertex/index allocation.
export function mapPropBatches(surfaces,plan,occlusion=null){
 const families=new Map(),records=[],meshes=[],size=new T.Vector2();let hierarchy;
 for(const prototype of plan.prototypes)for(const part of prototype.parts){const source=surfaces[part.chunk],key=source.family+':'+prototype.closed;let family=families.get(key);if(!family){family={source,closed:prototype.closed,parts:[]};families.set(key,family);}family.parts.push({part,instances:prototype.instances});}
 for(const {source,closed,parts}of families.values()){
  let vertices=0,indices=0,instances=0;for(const data of parts){const unique=new Map(),ranges=[];let count=0;for(const level of data.part.levels){let range=unique.get(level.index);if(!range){range={start:count,count:level.index.length,error:level.error};unique.set(level.index,range);count+=level.index.length;}ranges.push(range);}const index=new Uint32Array(count);for(const[ix,range]of unique)index.set(ix,range.start);const original=surfaces[data.part.chunk].geometry;data.geometry=compactSurface(original,index,{omitUV:true});data.ranges=ranges;vertices+=data.geometry.attributes.position.count;indices+=count;instances+=data.instances.length;}
  const material=propMaterial(source.material,closed),depth=propMaterial(source.material,closed,true),mesh=new T.BatchedMesh(instances,vertices,indices,material),draws=[];mesh.customDepthMaterial=depth;mesh.name='map-props:'+source.family;mesh.userData.staticMapBatch=true;mesh.userData.sharedMapProps=true;mesh.castShadow=true;mesh.receiveShadow=true;mesh.perObjectFrustumCulled=false;mesh.sortObjects=false;
  for(const data of parts){const base=mesh.addGeometry(data.geometry),ids=data.ranges.map(range=>mesh.addGeometryView(base,range.start,range.count));for(const instance of data.instances){const id=mesh.addInstance(ids[0]),matrix=new T.Matrix4().makeTranslation(...instance.offset),box=new T.Box3(new T.Vector3(...instance.bounds.slice(0,3)),new T.Vector3(...instance.bounds.slice(3))).expandByScalar(instance.error);mesh.setMatrixAt(id,matrix);const record={box};records.push(record);draws.push({id,ids,ranges:data.ranges,error:instance.error,box,record,level:0,visible:true,mainLevel:0});}data.geometry.dispose();delete data.geometry;}
  const before=mesh.onBeforeRender.bind(mesh);mesh.onBeforeRender=(renderer,scene,camera,geometry,paint)=>{const height=renderer.getDrawingBufferSize(size).y;hierarchy.prepare(camera,height);const exact=renderer.userData?.exactMapVisuals===true;if(mesh.userData.visibilityVersion!==hierarchy.version||mesh.userData.exactVisuals!==exact){mesh.userData.visibilityVersion=hierarchy.version;mesh.userData.exactVisuals=exact;const p=camera.projectionMatrix.elements,v=camera.matrixWorldInverse.elements,focal=height*.5*Math.abs(p[5]),angle=Math.sqrt(1+1/(p[0]*p[0])+1/(p[5]*p[5]));mesh.userData.lodCounts=[0,0,0,0];for(const d of draws){const visible=!!hierarchy.flags[d.record.visibilityId];if(visible!==d.visible){mesh.setVisibleAt(d.id,visible);d.visible=visible;}let level=0;if(visible&&camera.isPerspectiveCamera&&!exact){const b=d.box,depth=-(v[2]*(v[2]>=0?b.max.x:b.min.x)+v[6]*(v[6]>=0?b.max.y:b.min.y)+v[10]*(v[10]>=0?b.max.z:b.min.z)+v[14]);for(let j=1;j<d.ranges.length;j++){const error=d.ranges[j].error+d.error;if(depth>error+camera.near&&focal*angle*error/(depth-error)<=1.8)level=j;}const old=d.mainLevel,error=d.ranges[old].error+d.error;if(old>level&&depth>error+camera.near&&focal*angle*error/(depth-error)<=2)level=old;d.mainLevel=level;}if(level!==d.level){mesh.setGeometryIdAt(d.id,d.ids[level]);d.level=level;}if(visible)mesh.userData.lodCounts[level]++;}}before(renderer,scene,camera,geometry,paint);};
  const dispose=mesh.dispose.bind(mesh);let disposed=false;mesh.dispose=()=>{if(disposed)return;disposed=true;dispose();material.dispose();depth.dispose();};mesh.computeBoundingBox();mesh.computeBoundingSphere();mesh.updateMatrixWorld(true);mesh.matrixAutoUpdate=false;mesh.matrixWorldAutoUpdate=false;meshes.push(mesh);
 }
 hierarchy=new ClusterVisibility(records,occlusion);for(const mesh of meshes)mesh.userData.clusterVisibility=hierarchy;return meshes;
}

function propMaterial(source,closed,depth=false){
 const side=closed?T.FrontSide:source.side,material=depth?new T.MeshDepthMaterial({side,depthPacking:T.RGBADepthPacking,alphaMap:source.alphaMap,map:source.alphaTest?source.map:null,alphaTest:source.alphaTest}):optimizeMapMaterial(source),compile=depth?()=>{}:source.onBeforeCompile.bind(source),key=depth?'depth':source.customProgramCacheKey();material.side=side;material.shadowSide=source.shadowSide??source.side;
 material.onBeforeCompile=shader=>{compile(shader);shader.vertexShader='attribute float mapUvAxis;attribute vec2 mapUvOffset;\n'+shader.vertexShader.replace('#include <batching_vertex>','').replace('void main() {','void main() {\n#include <batching_vertex>\nvec3 mapPropPosition=(batchingMatrix*vec4(position,1.)).xyz;\nvec3 mapPropNormal=mat3(batchingMatrix)*normal;').replace('#include <uv_vertex>','#define uv (vec2(mapUvAxis<.5?mapPropPosition.z:mapPropPosition.x,(mapUvAxis>.5&&mapUvAxis<1.5)?mapPropPosition.z:mapPropPosition.y)*.45+mapUvOffset/81920.)\n#include <uv_vertex>\n#undef uv').replaceAll('vArtPosition=position','vArtPosition=mapPropPosition').replaceAll('vMapArtPosition=position','vMapArtPosition=mapPropPosition').replaceAll('vMapArtNormal=normal','vMapArtNormal=mapPropNormal');};material.customProgramCacheKey=()=>key+':shared-map-props-v1:'+depth;return material;
}
